  var p=actor(t);var w=wolf(t,p);t.assertTrue(!GreyWolfStory.action(p,w,-1,2)&&!GreyWolfStory.action(p,w,999,2)&&!GreyWolfStory.action(p,w,0,999),"invalid action");p.moveTo(w.position().add(0,0,9));t.assertTrue(!GreyWolfStory.action(p,w,0,0),"remote action");p.moveTo(w.position().add(0,0,2));p.setGameMode(GameType.SPECTATOR);t.assertTrue(!GreyWolfStory.action(p,w,0,0),"spectator");t.succeed();
