 @GameTest(template="empty") public static void nativeMagicMultiplierMarkAndSafePolarity(GameTestHelper t)throws Exception{
  var p=actor(t);equip(p,"belt",FinistItems.QUIVER.get());var bow=new ItemStack(FinistItems.BOW.get());var e=enemy(t,p);var a=shot(t,p,bow);a.setCritArrow(false);a.setDeltaMovement(0,0,3.6);impact(a,e);float damage=100-e.getHealth();t.assertTrue(Math.abs(damage-16.5)<.001,"exact native x1.5 damage="+damage);t.assertTrue(e.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS)&&FinistMarks.target(p)==e,"effect/mark");t.assertTrue(PathData.data(p).getCompound("FinistMark").getLong("Until")==GreyPackRing.now(p)+1200,"mark TTL");a=shot(t,p,bow);t.assertTrue(a instanceof FinistArrow&&((FinistArrow)a).guide().equals(e.getUUID()),"follow-up guide");var undead=EntityType.ZOMBIE.create(t.getLevel());undead.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);undead.setHealth(100);undead.moveTo(p.position().add(0,0,7));p.setShiftKeyDown(true);a=shot(t,p,bow);a.setCritArrow(false);a.setDeltaMovement(0,0,3.6);impact(a,undead);t.assertTrue(undead.getHealth()<84&&undead.isInvertedHealAndHarm()&&!undead.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS),"undead healed or wrong status "+undead.getHealth());t.succeed();
 }
 @GameTest(template="empty") public static void incidentalCollisionIsNormalAndManualRetarget(GameTestHelper t)throws Exception{
  var p=actor(t);equip(p,"belt",FinistItems.QUIVER.get());var bow=new ItemStack(FinistItems.BOW.get());p.setItemSlot(EquipmentSlot.MAINHAND,bow);var first=enemy(t,p);var second=enemy(t,p);second.moveTo(p.position().add(2,0,5));FinistMarks.hit(p,first,true);var a=shot(t,p,bow);a.setCritArrow(false);a.setDeltaMovement(0,0,3.6);impact(a,second);t.assertTrue(Math.abs(100-second.getHealth()-11)<.001&&!second.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS)&&FinistMarks.target(p)==first,"incidental enhancement/retarget");p.setShiftKeyDown(true);a=shot(t,p,bow);a.setCritArrow(false);a.setDeltaMovement(0,0,3.6);second.invulnerableTime=0;impact(a,second);t.assertTrue(FinistMarks.target(p)==second,"manual retarget failed");second.discard();t.assertTrue(FinistMarks.target(p)==null,"unloaded mark remains");t.succeed();
 }
 @GameTest(template="empty") public static void nativeProjectileStoneCollision(GameTestHelper t){
  var p=actor(t);var a=new FinistArrow(p,t.getLevel(),new ItemStack(FinistItems.BOW.get()));a.moveTo(p.position().add(0,.8,0));a.setDeltaMovement(0,0,3.6);var wall=p.blockPosition().offset(0,0,2);for(int y=0;y<4;y++)t.getLevel().setBlockAndUpdate(wall.above(y),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());t.getLevel().addFreshEntity(a);a.tick();var n=new CompoundTag();a.saveWithoutId(n);t.assertTrue(a.getZ()<wall.getZ()+.1&&n.getBoolean("inGround"),"stone collision ignored "+a.position());t.succeed();
 }
 @GameTest(template="empty") public static void nativeEnchantAndRunicAnvilPreserveWeapon(GameTestHelper t){
  var p=actor(t);var bow=new ItemStack(FinistItems.BOW.get());var ench=p.registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolderOrThrow(Enchantments.POWER);t.assertTrue(ench.value().isSupportedItem(bow),"Power support");bow.enchant(ench,3);bow.setDamageValue(17);bow.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("FinistProbe"));Runes.write(bow,2,List.of());var inv=new SimpleContainer(2);inv.setItem(0,bow);String compatible=RuneBalance.DEFINITIONS.stream().filter(d->d.tier()==2&&Runes.compatible(bow,d.id())).map(d->d.id()).findFirst().orElseThrow();inv.setItem(1,new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("slavicmyths","rune_"+compatible))));var preview=Runes.preview(inv,1);t.assertTrue(!preview.isEmpty()&&Runes.has(preview,compatible)&&preview.getDamageValue()==17&&preview.getEnchantments().getLevel(ench)==3&&preview.getHoverName().getString().equals("FinistProbe"),"anvil lost data");p.setItemSlot(EquipmentSlot.MAINHAND,bow);var e=enemy(t,p);var a=shot(t,p,bow);a.setCritArrow(false);a.setDeltaMovement(0,0,3.6);try{impact(a,e);}catch(Exception ex){throw new RuntimeException(ex);}t.assertTrue(100-e.getHealth()>11,"Power had no native effect");t.succeed();
 }

 @GameTest(template="empty") public static void nativeBoundLikhoDeathAndUnexpectedRemoval(GameTestHelper t){
  var p=actor(t);active(p,2);var records=org.slavicmyths.hunt.HuntRecords.get(t.getLevel());var boss=ModEntities.LIKHO_ONE_EYED.get().create(t.getLevel());boss.moveTo(p.position().add(2,0,0));boss.encounter="story_native_"+UUID.randomUUID();var encounter=new org.slavicmyths.hunt.HuntRecords.Boss(boss.encounter,org.slavicmyths.hunt.BossKind.LIKHO,boss.blockPosition(),false);encounter.target=boss.getUUID();encounter.active=true;records.bosses.put(encounter.key,encounter);var q=GreyWolfStory.quest(p,2);q.putString("BossKey",encounter.key);q.putUUID("Target",boss.getUUID());t.getLevel().addFreshEntity(boss);boss.discard();t.assertTrue(!encounter.active&&GreyWolfStory.stage(p,2)==GreyWolfStory.Stage.ACTIVE,"discard credited or encounter stuck");GreyWolfStory.data(p).putLong("WolfHome",boss.blockPosition().offset(-1250,0,0).asLong());GreyWolfStory.refreshTarget(p);t.assertTrue(q.getString("BossKey").isEmpty(),"discard did not rebind");records.bosses.remove(encounter.key);
  boss=ModEntities.LIKHO_ONE_EYED.get().create(t.getLevel());boss.moveTo(p.position().add(2,0,0));boss.encounter="story_native_"+UUID.randomUUID();encounter=new org.slavicmyths.hunt.HuntRecords.Boss(boss.encounter,org.slavicmyths.hunt.BossKind.LIKHO,boss.blockPosition(),false);encounter.target=boss.getUUID();encounter.active=true;records.bosses.put(encounter.key,encounter);q.putString("BossKey",encounter.key);q.putUUID("Target",boss.getUUID());boss.hurt(boss.damageSources().playerAttack(p),10000);t.assertTrue(!encounter.active&&GreyWolfStory.stage(p,2)==GreyWolfStory.Stage.REWARD_READY,"real bound death not credited");records.bosses.remove(encounter.key);t.succeed();
 }
